const cellKey = (x: number, y: number): string => `${x},${y}`;

const survivesWithNeighborCount = (count: number): boolean =>
  count === 2 || count === 3;

export function nextGeneration(cells: Cell[]): Cell[] {
  const alive = new Set(cells.map(([x, y]) => cellKey(x, y)));

  const countAliveNeighbors = ([x, y]: Cell): number =>
    NEIGHBOR_OFFSETS.filter(([dx, dy]) => alive.has(cellKey(x + dx, y + dy))).length;

  return cells.filter((cell) => survivesWithNeighborCount(countAliveNeighbors(cell)));
}
